function getH3CellsAtResolution(resolution) {
    if (resolution === undefined) {
        resolution = 0;
    } else if (resolution &gt; 3) {
        resolution = 3;
    }
    let cells = h3.getRes0Cells();
    if (resolution &gt; 0) {
        let cells1 = [];
        for (const cell of cells) {
            cells1 = cells1.concat(h3.cellToChildren(cell, resolution));
        }
        cells = cells1;
    }
    return cells
}

